-- Lucas Marketing AI v2 — Supabase
create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.memberships(org_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','admin','strategist','member','viewer')),created_at timestamptz not null default now(),primary key(org_id,user_id));
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,name text not null,niche text,city text,ticket numeric(12,2) default 0,budget numeric(12,2) default 0,goal text,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete cascade,title text not null,status text not null default 'planning',progress int not null default 0 check(progress between 0 and 100),lead_agent text,deadline date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.content_items(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete cascade,title text not null,content_type text,status text not null default 'idea',scheduled_for timestamptz,brief jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,name text not null,phone text,email text,source text,stage text not null default 'new',potential_value numeric(12,2) default 0,owner_id uuid references auth.users(id) on delete set null,last_contact_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,agent_id text not null,title text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,role text not null check(role in('user','assistant','system','tool')),content text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.automations(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete cascade,name text not null,trigger_type text not null,action_type text not null,config jsonb not null default '{}'::jsonb,is_active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.integrations(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,provider text not null,status text not null default 'disconnected',external_account_id text,metadata jsonb not null default '{}'::jsonb,last_sync_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,provider));
create table if not exists public.webhook_events(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,event_type text not null,payload jsonb not null default '{}'::jsonb,processed boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.app_state(org_id uuid primary key references public.organizations(id) on delete cascade,data jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated by default as identity primary key,org_id uuid references public.organizations(id) on delete set null,user_id uuid references auth.users(id) on delete set null,action text not null,entity_type text,entity_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.memberships where org_id=target_org and user_id=auth.uid())$$;
create or replace function public.has_org_role(target_org uuid,allowed text[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.memberships where org_id=target_org and user_id=auth.uid() and role=any(allowed))$$;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
do $$declare t text;begin foreach t in array array['organizations','clients','projects','content_items','leads','conversations','automations','integrations'] loop execute format('drop trigger if exists set_updated_at on public.%I',t);execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t);end loop;end$$;
create or replace function public.bootstrap_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare new_org uuid;begin insert into public.organizations(name,slug) values(coalesce(new.raw_user_meta_data->>'company','Minha Agência'),lower(regexp_replace(coalesce(new.raw_user_meta_data->>'company','agencia'),'[^a-zA-Z0-9]+','-','g'))||'-'||substr(new.id::text,1,8)) returning id into new_org;insert into public.memberships(org_id,user_id,role) values(new_org,new.id,'owner');return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.bootstrap_new_user();
alter table public.organizations enable row level security;alter table public.memberships enable row level security;alter table public.clients enable row level security;alter table public.projects enable row level security;alter table public.content_items enable row level security;alter table public.leads enable row level security;alter table public.conversations enable row level security;alter table public.messages enable row level security;alter table public.automations enable row level security;alter table public.integrations enable row level security;alter table public.webhook_events enable row level security;alter table public.app_state enable row level security;alter table public.audit_logs enable row level security;
create policy "org_read" on public.organizations for select using(public.is_org_member(id));
create policy "org_update_admin" on public.organizations for update using(public.has_org_role(id,array['owner','admin'])) with check(public.has_org_role(id,array['owner','admin']));
create policy "membership_read" on public.memberships for select using(public.is_org_member(org_id));
create policy "membership_admin" on public.memberships for all using(public.has_org_role(org_id,array['owner','admin'])) with check(public.has_org_role(org_id,array['owner','admin']));
do $$declare t text;begin foreach t in array array['clients','projects','content_items','leads','conversations','automations','integrations'] loop execute format('create policy %I on public.%I for select using(public.is_org_member(org_id))',t||'_read',t);execute format('create policy %I on public.%I for insert with check(public.has_org_role(org_id,array[''owner'',''admin'',''strategist'',''member'']))',t||'_insert',t);execute format('create policy %I on public.%I for update using(public.has_org_role(org_id,array[''owner'',''admin'',''strategist'',''member''])) with check(public.has_org_role(org_id,array[''owner'',''admin'',''strategist'',''member'']))',t||'_update',t);execute format('create policy %I on public.%I for delete using(public.has_org_role(org_id,array[''owner'',''admin'']))',t||'_delete',t);end loop;end$$;
create policy "messages_read" on public.messages for select using(exists(select 1 from public.conversations c where c.id=conversation_id and public.is_org_member(c.org_id)));
create policy "messages_insert" on public.messages for insert with check(exists(select 1 from public.conversations c where c.id=conversation_id and public.has_org_role(c.org_id,array['owner','admin','strategist','member'])));
create policy "app_state_read" on public.app_state for select using(public.is_org_member(org_id));
create policy "app_state_write" on public.app_state for all using(public.has_org_role(org_id,array['owner','admin','strategist','member'])) with check(public.has_org_role(org_id,array['owner','admin','strategist','member']));
create policy "audit_admin_read" on public.audit_logs for select using(public.has_org_role(org_id,array['owner','admin']));
create index if not exists idx_clients_org on public.clients(org_id);create index if not exists idx_projects_client on public.projects(client_id);create index if not exists idx_content_client on public.content_items(client_id);create index if not exists idx_leads_org_stage on public.leads(org_id,stage);create index if not exists idx_conversations_org on public.conversations(org_id,created_at desc);create index if not exists idx_messages_conversation on public.messages(conversation_id,created_at);create index if not exists idx_audit_org_time on public.audit_logs(org_id,created_at desc);
